package com.bank.payments.application;

import com.bank.payments.adapters.in.rest.PayOrderRequest;
import com.bank.payments.adapters.in.rest.PayOrderResponse;
import com.bank.payments.domain.error.BusinessError;
import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.model.PaymentOrder;
import com.bank.payments.domain.port.AccountRepository;
import com.bank.payments.domain.port.MovementGateway;
import com.bank.payments.domain.port.OrderRepository;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Optional;

/** Application service of PayOrder (legacy PAGOORD, with the debit of PAGODEB invoked in-process). */
public class PayOrderService {

    private static final String LEGACY_CODE = "-1";
    private static final BigDecimal LIMIT_NO_COMMISSION = new BigDecimal("50000");

    private final OrderRepository orderRepository;
    private final AccountRepository accountRepository;
    private final MovementGateway movementGateway;

    public PayOrderService(OrderRepository orderRepository,
                           AccountRepository accountRepository,
                           MovementGateway movementGateway) {
        this.orderRepository = orderRepository;
        this.accountRepository = accountRepository;
        this.movementGateway = movementGateway;
    }

    public PayOrderResponse execute(PayOrderRequest request) {
        // 2100-VALIDAR-ENTRADA
        String orderText = fix(request.orderNumber(), 7);
        String accountType = fix(request.accountType(), 3);
        String channel = fix(request.channel(), 3);
        String key = fix(request.approvalKey(), 6);

        if (!isNumeric(orderText) || isAllZeros(orderText)) {
            throw reject("INVALID_ORDER_NUMBER", "NUMERO DE ORDEN INVALIDO");
        }
        if (!accountType.equals("CTE") && !accountType.equals("AHO") && !accountType.equals("VIR")) {
            throw reject("ACCOUNT_TYPE_NOT_ALLOWED", "TIPO DE CUENTA NO PERMITIDO");
        }
        if (!channel.equals("WEB") && !channel.equals("OFI")) {
            throw reject("CHANNEL_NOT_ALLOWED", "CANAL NO PERMITIDO");
        }
        if (channel.equals("OFI") && key.isBlank()) {
            throw reject("APPROVAL_KEY_REQUIRED", "CLAVE DE APROBACION REQUERIDA");
        }

        // 2200-LEER-ORDEN
        Integer orderNumber = Integer.valueOf(orderText);
        Optional<PaymentOrder> found = orderRepository.findByKeyForUpdate(orderNumber, request.companyId());
        if (found.isEmpty()) {
            throw reject("ORDER_NOT_FOUND", "ORDEN NO EXISTE");
        }
        PaymentOrder order = found.get();
        if (!"P".equals(order.status())) {
            throw reject("ORDER_NOT_PENDING", "ORDEN NO ESTA PENDIENTE");
        }
        BigDecimal enteredValue = request.value().setScale(2, RoundingMode.DOWN);
        if (enteredValue.compareTo(order.orderValue()) != 0) {
            throw reject("AMOUNT_MISMATCH", "VALOR NO COINCIDE CON LA ORDEN");
        }

        // 2300-CALCULAR-COMISION
        BigDecimal commission;
        if (order.orderValue().compareTo(LIMIT_NO_COMMISSION) >= 0) {
            commission = new BigDecimal("0.00");
        } else if (channel.equals("WEB")) {
            commission = new BigDecimal("1.00");
        } else {
            commission = new BigDecimal("2.50");
        }
        BigDecimal total = order.orderValue().add(commission);

        // 2400-DEBITAR-CUENTA (PAGODEB)
        String debitResponse = debit(request.accountNumber(), accountType, total);
        switch (debitResponse) {
            case "00":
                break;
            case "10":
                throw reject("ACCOUNT_INACTIVE", "CUENTA INACTIVA");
            case "20":
                throw reject("INSUFFICIENT_FUNDS", "SALDO INSUFICIENTE");
            default:
                throw reject("INVALID_ACCOUNT", "CUENTA NO VALIDA");
        }

        // 2500-REGISTRAR-PAGO
        long movementNumber = movementGateway.registerMovement(order.orderNumber());
        orderRepository.markPaid(order.orderNumber(), order.companyId(), movementNumber, commission);

        // 2600-ENVIAR-RESULTADO
        return new PayOrderResponse(order.orderNumber(), commission, movementNumber, "PAGO REALIZADO");
    }

    /** Logic of PAGODEB: returns the response code. */
    private String debit(Long accountNumber, String accountType, BigDecimal amount) {
        Optional<Account> found = accountRepository.findByNumberForUpdate(accountNumber);
        if (found.isEmpty()) {
            return "30";
        }
        Account account = found.get();
        if (!fix(account.accountType(), 3).equals(accountType)) {
            return "40";
        }
        if (!"A".equals(account.status())) {
            return "10";
        }
        if (account.balance().compareTo(amount) < 0) {
            return "20";
        }
        accountRepository.updateBalance(accountNumber, account.balance().subtract(amount));
        return "00";
    }

    private static BusinessError reject(String code, String message) {
        return new BusinessError(code, LEGACY_CODE, message);
    }

    /** Emulates a fixed-length PIC X field: null as spaces, padded or truncated on the right. */
    private static String fix(String value, int length) {
        String v = value == null ? "" : value;
        if (v.length() > length) {
            return v.substring(0, length);
        }
        StringBuilder sb = new StringBuilder(v);
        while (sb.length() < length) {
            sb.append(' ');
        }
        return sb.toString();
    }

    private static boolean isNumeric(String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }

    private static boolean isAllZeros(String s) {
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != '0') {
                return false;
            }
        }
        return true;
    }
}
